package com.shopsphere;import static org.junit.jupiter.api.Assertions.*;import java.util.UUID;import org.junit.jupiter.api.*;class InventoryServiceTest{InventoryService service;UUID id;@BeforeEach void setup(){service=new InventoryService(new InventoryRepository.InMemory());id=UUID.randomUUID();service.set(id,"SKU-1",10,2);}@Test void reserveAndReleaseMaintainTotals(){assertEquals(7,service.reserve(id,3).sellable());Inventory released=service.release(id,2);assertEquals(1,released.quantityReserved());assertEquals(9,released.sellable());}@Test void preventsInsufficientAndInvalidRelease(){assertThrows(BusinessException.class,()->service.reserve(id,11));service.reserve(id,2);assertThrows(BusinessException.class,()->service.release(id,3));}}
